def classify(n,F,pts=None,numeric=False,domain='',extra='',graph=False):
 fx=S.diff(F,x);fy=S.diff(F,y);H=S.hessian(F,(x,y));det=S.det(H)
 if pts is None:pts=[(a[x],a[y]) for a in S.solve([fx,fy],(x,y),dict=True) if x in a and y in a and a[x].is_real is not False and a[y].is_real is not False]
 ks=['정지식: '+M(fx)+'=0, '+M(fy)+'=0.'];es=['Stationary equations: '+M(fx)+'=0, '+M(fy)+'=0.'];aks=[];aes=[]
