def polygon(n,F,vertices):
 # Edge-restricted derivatives enumerate every boundary candidate.
 candidates=set(vertices);details=[]
 for i,P in enumerate(vertices):
  Q=vertices[(i+1)%len(vertices)];xx=P[0]+t*(Q[0]-P[0]);yy=P[1]+t*(Q[1]-P[1]);g=S.expand(F.subs({x:xx,y:yy},simultaneous=True));roots=S.solve(S.diff(g,t),t)
  vals=[a for a in roots if a.is_real and 0<=float(a)<=1]
  for a in vals:candidates.add((S.simplify(xx.subs(t,a)),S.simplify(yy.subs(t,a))))
  details.append(M(g)+', 0≤t≤1; t='+(', '.join(M(a) for a in vals) or '—'))
 for pt in S.solve([S.diff(F,x),S.diff(F,y)],(x,y),dict=True):
  if x not in pt or y not in pt or pt[x].is_real is False or pt[y].is_real is False:continue
  xx,yy=pt[x],pt[y];cross=[float((vertices[(i+1)%len(vertices)][0]-a)*(yy-b)-(vertices[(i+1)%len(vertices)][1]-b)*(xx-a)) for i,(a,b) in enumerate(vertices)]
  if min(cross)>=-1e-9 or max(cross)<=1e-9:candidates.add((xx,yy))
 table=sorted([(S.simplify(F.subs({x:a,y:b})),a,b) for a,b in candidates],key=lambda row:float(row[0]));mn=table[0][0];mx=table[-1][0];mins=[S.Tuple(a,b) for val,a,b in table if S.simplify(val-mn)==0];maxs=[S.Tuple(a,b) for val,a,b in table if S.simplify(val-mx)==0]
 vals='; '.join(M(S.Tuple(a,b))+': '+M(val) for val,a,b in table)
 st='f='+M(F)+', D vertices='+str(vertices)+'. '
 add(n,st+'D에서 절대최대·최소를 구하라.',st+'Find absolute extrema on D.',['내부에서 fx=fy=0을 풀고 D 안의 점만 남긴다.','순서대로 각 변을 P+t(Q−P)로 쓰면 다음 단변수식과 내부 정지 매개변수를 얻는다: '+'; '.join(details),'꼭짓점·변 정지점·내부 정지점의 값: '+vals],['Solve fx=fy=0 in the interior, keeping points in D.','On successive edges P+t(Q−P), the restricted polynomials and stationary parameters are: '+'; '.join(details),'Values at all vertex, edge, and interior candidates: '+vals],'최소 '+M(mn)+' at '+','.join(M(a) for a in mins)+'; 최대 '+M(mx)+' at '+','.join(M(a) for a in maxs),'Minimum '+M(mn)+' at '+','.join(M(a) for a in mins)+'; maximum '+M(mx)+' at '+','.join(M(a) for a in maxs),'닫히고 유계인 다각형에서 연속이므로 극값이 존재하며 모든 경계 변을 따로 미분했다.','Continuity on the compact polygon guarantees extrema, and every edge was separately differentiated.')
for row in [(33,x*x+y*y-2*x,[(2,0),(0,2),(0,-2)]),(34,x+y-x*y,[(0,0),(0,2),(4,0)]),(35,x*x+y*y+x*x*y+4,[(-1,-1),(1,-1),(1,1),(-1,1)]),(36,x*x+x*y+y*y-6*y,[(-3,0),(3,0),(3,5),(-3,5)]),(37,x*x+2*y*y-2*x-4*y+1,[(0,0),(2,0),(2,3),(0,3)]),(40,x**3-3*x-y**3+12*y,[(-2,3),(2,3),(2,2),(-2,-2)])]:polygon(*row)
