add(41,'f='+M(F)+'가 정지점이 두 개뿐이고 둘 다 극대임을 보여라. 두 봉우리가 보이는 그래프를 그려라.','Show f='+M(F)+' has exactly two stationary points, both maxima, and plot the two peaks.',['fy=−2x²(x²y−x−1). x=0이면 fx=−2≠0이므로 정지점이 아니다.','x≠0이면 x²y−x−1=0, fx=−4x(x²−1)=0이므로 x=±1. 이에 y=2 또는0이다.','f는 두 음의 제곱의 합으로0 이하이며 두 점에서0이다.'],['fy=−2x²(x²y−x−1). At x=0,fx=−2≠0, so there is no stationary point.','For x≠0, x²y−x−1=0 and fx=−4x(x²−1)=0, hence x=±1 and y=2 or0.','As a sum of negative squares, f≤0 and equals0 at both points.'],'(1,2), (−1,0)에서 절대극대0. 다른 정지점과 극소는 없다.','Absolute maxima0 at (1,2) and (−1,0); no other stationary points or minima.');plots[41]=(F,(-1.7,1.7,-1,3))
F=3*x*S.exp(y)-x**3-S.exp(3*y)
add(42,'f='+M(F)+'가 유일한 정지점에서 국소 극대이지만 절대극대는 아님을 보여주고 그래프로 설명하라.','Show f='+M(F)+' has a unique stationary point that is a local but not absolute maximum; illustrate graphically.',['fx=3eʸ−3x²=0, fy=3xeʸ−3e³ʸ=0에서 x=e²ʸ>0과 eʸ=x²를 얻어 (x,y)=(1,0).','헤세행렬 [[−6,3],[3,−6]]의 D=27>0,fxx<0이므로 극대, f=1.','그러나 y=0에서 f=3x−x³−1→∞ as x→−∞이다.'],['The stationary equations give x=e²ʸ>0 and eʸ=x², forcing (1,0).','The Hessian [[−6,3],[3,−6]] has D=27>0 and fxx<0, yielding local maximum1.','But along y=0, f=3x−x³−1→∞ as x→−∞.'],'유일한 정지점 (1,0), 국소극대1; 절대최대는 없다.','Unique stationary point (1,0), local maximum1; no absolute maximum.');plots[42]=(F,(-3,2,-1,1))
add(43,'점 (2,0,−3)에서 평면 x+y+z=1까지 최단거리를 구하라.','Find the shortest distance from (2,0,−3) to x+y+z=1.',['평면 법선은 (1,1,1). 점을 좌변−우변에 넣으면−2이다.','법선 길이√3으로 절댓값을 나누면 거리2/√3. 수선발은 (8/3,2/3,−7/3)이다.'],['The plane normal is (1,1,1), and its defining expression at the point is−2.','Divide the absolute value by normal length√3 to obtain2/√3; the foot is (8/3,2/3,−7/3).'],r'\(2/\sqrt3\).',r'\(2/\sqrt3\).')
add(44,'평면 x−2y+3z=6에서 (0,1,1)에 가장 가까운 점을 구하라.','Find the point on x−2y+3z=6 closest to (0,1,1).',['법선 n=(1,−2,3),||n||²=14이다.','수선발은 P+tn이고 평면에 넣으면1+14t=6, t=5/14이다.'],['The normal is n=(1,−2,3), with squared norm14.','The foot P+tn satisfies1+14t=6, so t=5/14.'],'(5/14,2/7,29/14).','(5/14,2/7,29/14).')
add(45,r'원뿔 \(z^2=x^2+y^2\)에서 (4,2,0)에 가장 가까운 점들을 구하라.',r'Find the closest points on \(z^2=x^2+y^2\) to (4,2,0).',['제약식을 거리제곱에 대입하면 (x−4)²+(y−2)²+x²+y².','이는 2(x−2)²+2(y−1)²+10이므로 x=2,y=1, z=±√5에서 최소이다.'],['Substitute the constraint into squared distance: (x−4)²+(y−2)²+x²+y².','This is2(x−2)²+2(y−1)²+10, minimized at x=2,y=1,z=±√5.'],'(2,1,±√5), 최단거리√10.','(2,1,±√5), shortest distance√10.')
add(46,'곡면 y²=9+xz에서 원점에 가장 가까운 점들을 구하라.','Find points of y²=9+xz closest to the origin.',['거리제곱=x²+y²+z²=9+x²+xz+z².','x²+xz+z²=(x+z/2)²+3z²/4≥0, 등호는 x=z=0이다.'],['Squared distance is9+x²+xz+z².','Complete the square: x²+xz+z²=(x+z/2)²+3z²/4≥0, with equality only at x=z=0.'],'(0,±3,0), 최단거리3.','(0,±3,0), shortest distance3.')
for n,total,objective in [(47,100,'product'),(48,12,'squares')]:
 if objective=='product':ks=['양수 a+b+c=100에서 AM–GM으로 abc≤(100/3)³이다.','등호는 세 수가 같을 때 성립한다.'];es=['AM–GM gives abc≤(100/3)³ for positive a+b+c=100.','Equality requires all three numbers equal.'];ka='세 수100/3, 최대곱1,000,000/27.';ea='All three are100/3; maximum product1,000,000/27.'
 else:ks=['a²+b²+c²≥(a+b+c)²/3=48이다.','등호 조건은 a=b=c=4.'];es=['a²+b²+c²≥(a+b+c)²/3=48.','Equality holds at a=b=c=4.'];ka='세 수4, 제곱합 최소48.';ea='All three are4; minimum sum of squares48.'
 add(n,f'합이{total}인 세 양수의 '+('곱을 최대화하라.' if objective=='product' else '제곱합을 최소화하라.'),f'For three positive numbers summing to{total}, '+('maximize their product.' if objective=='product' else 'minimize their sum of squares.'),ks,es,ka,ea)
add(49,'반지름 r의 구에 내접하는 직육면체의 최대부피를 구하라.','Find the largest volume of a rectangular box inscribed in a sphere of radius r.',['변 길이 a,b,c에 대해 대각선 제약 a²+b²+c²=4r²이다.','AM–GM으로 (abc)²≤(4r²/3)³, 등호는 a=b=c.'],['Side lengths satisfy a²+b²+c²=4r².','AM–GM gives (abc)²≤(4r²/3)³, with equality at a=b=c.'],r'변 \(2r/\sqrt3\), 최대부피 \(8r^3/(3\sqrt3)\).',r'Sides \(2r/\sqrt3\); maximum volume \(8r^3/(3\sqrt3)\).')
add(50,'부피1000 cm³의 닫힌 직육면체에서 겉넓이를 최소화하는 치수를 구하라.','Find dimensions minimizing the surface area of a closed box of volume1000 cm³.',['S=2(ab+bc+ca), abc=1000.','ab+bc+ca≥3(abc)^(2/3)=300, 등호는 a=b=c=10.'],['S=2(ab+bc+ca), abc=1000.','ab+bc+ca≥3(abc)^(2/3)=300, with equality at a=b=c=10.'],'10×10×10 cm, 최소겉넓이600 cm².','10×10×10 cm; minimum surface area600 cm².')
add(51,'첫 팔분공간에서 좌표평면에 세 면을 두고 반대 꼭짓점이 x+2y+3z=6인 직육면체의 최대부피를 구하라.','Find the largest first-octant box with three faces in coordinate planes and opposite vertex on x+2y+3z=6.',['양수 x,2y,3z의 합은6. 곱6xyz≤2³이다.','등호는 x=2y=3z=2이다.'],['The positive quantities x,2y,3z sum to6, so6xyz≤2³.','Equality holds at x=2y=3z=2.'],'치수(2,1,2/3), 최대부피4/3.','Dimensions(2,1,2/3); maximum volume4/3.')
add(52,'겉넓이64 cm²의 닫힌 직육면체에서 최대부피의 치수를 구하라.','Find dimensions of the maximum-volume closed box with surface area64 cm².',['ab+bc+ca=32. AM–GM으로 (abc)²≤(32/3)³이다.','등호 조건 ab=bc=ca는 양수 치수가 모두 같음을 뜻한다.'],['ab+bc+ca=32, so AM–GM yields (abc)²≤(32/3)³.','Equality ab=bc=ca forces all positive side lengths equal.'],r'각 변 \(4\sqrt{2/3}\) cm.',r'Each side is \(4\sqrt{2/3}\) cm.')
add(53,'12개 모서리 길이의 합이 c인 직육면체의 최대부피 치수를 구하라.','Find dimensions maximizing a box’s volume when its twelve edges have total length c.',['4(a+b+d)=c, 따라서 abc 대신 abd≤((a+b+d)/3)³=(c/12)³.','등호는 a=b=d=c/12이다.'],['4(a+b+d)=c, and abd≤((a+b+d)/3)³=(c/12)³.','Equality requires a=b=d=c/12.'],'각 변c/12, 최대부피c³/1728.','Each side c/12; maximum volume c³/1728.')
add(54,'부피 V인 뚜껑 없는 수조의 밑면 재료는 옆면 유리의 면적당 가격5배이다. 재료비를 최소화하는 치수를 구하라.','An open aquarium of volume V has base material costing five times as much per area as glass sides. Find cost-minimizing dimensions.',['유리 단가로 나눈 비용 C=5ab+2h(a+b), h=V/(ab).','Ca=5b−2V/a²=0,Cb=5a−2V/b²=0으로 a=b, a³=2V/5. 비용은 경계에서 무한대로 가므로 이 유일한 정지점이 최소이다.'],['In glass-cost units C=5ab+2h(a+b), with h=V/(ab).','Stationarity gives5b−2V/a²=0 and5a−2V/b²=0, hence a=b and a³=2V/5. Cost diverges at domain extremes, so the unique stationary point is minimal.'],r'정사각 밑변 \((2V/5)^{1/3}\), 높이 \((25V/4)^{1/3}\).',r'Square base side \((2V/5)^{1/3}\); height \((25V/4)^{1/3}\).')
add(55,'부피32,000 cm³의 뚜껑 없는 직육면체 상자에서 종이를 최소화하는 치수를 구하라.','Find dimensions minimizing cardboard for an open box of volume32,000 cm³.',['밑변 a,b,높이 h에서 A=ab+2V/a+2V/b.','정지식 b=2V/a²,a=2V/b²는 a=b와 a³=64,000을 준다.'],['For base a,b and height h, A=ab+2V/a+2V/b.','Stationarity b=2V/a²,a=2V/b² gives a=b and a³=64,000.'],'밑면40×40 cm, 높이20 cm; 종이4800 cm².','Base40×40 cm, height20 cm; cardboard4800 cm².')
add(56,'건물 부피4000 m³, 밑변 a,b≥30 m, 높이h≥4 m. 동·서벽 손실10, 남·북벽8, 바닥1, 지붕5(단위/m²/day)이다. a는 동서 길이이다. (a) 비용 정의역을 그리고 (b) 제약하 최소 치수 (c) 벽 길이 제한을 없앤 개선 가능성을 구하라.','A4000 m³ building has base a,b≥30 m and height h≥4 m. East/west walls lose10, north/south walls8, floor1, roof5 units/m²/day; a is east–west length. (a) Sketch the domain; (b) minimize with constraints; (c) consider removing wall-length restrictions.',['(a) h=4000/(ab), 따라서 a≥30,b≥30,ab≤1000. 비용 H=16ah+20bh+6ab=64000/b+80000/a+6ab.','(b) 이 영역에서 Ha=−80000/a²+6b>0,Hb=−64000/b²+6a>0. 따라서 가장 작은 a=b=30이 최소이다. h=40/9, H=10200.','(c) 제한을 없애면 정지식에서 a/b=5/4, b³=25600/3, h=3b/8. 이 점은 h≥4도 만족하고 더 작은 손실을 준다.'],['(a) Since h=4000/(ab), the domain is a≥30,b≥30,ab≤1000. Heat loss is H=16ah+20bh+6ab=64000/b+80000/a+6ab.','(b) Throughout this region Ha=−80000/a²+6b>0 and Hb=−64000/b²+6a>0. Thus a=b=30 minimizes H, with h=40/9 and H=10200.','(c) Removing length restrictions yields a/b=5/4,b³=25600/3,h=3b/8. This also satisfies h≥4 and yields lower loss.'],r'(a) a≥30,b≥30,ab≤1000. (b) 30×30×(40/9) m. (c) \(b=(25600/3)^{1/3},a=5b/4,h=3b/8\); 가능.',r'(a) a≥30,b≥30,ab≤1000. (b) 30×30×(40/9) m. (c) \(b=(25600/3)^{1/3},a=5b/4,h=3b/8\); yes.','세 양의 비용 항에 AM–GM을 적용하면 자유 최적점의 전역 최소성도 확인된다.','AM–GM on the three positive cost terms also verifies the unconstrained global minimum.',['a','b','c'])
add(57,'직육면체 대각선 길이가 L일 때 가능한 최대부피를 구하라.','Find the largest volume of a box whose diagonal has length L.',['a²+b²+c²=L²에 AM–GM을 적용한다.','(abc)²≤(L²/3)³이고 등호는 a=b=c이다.'],['Apply AM–GM to a²+b²+c²=L².','(abc)²≤(L²/3)³, with equality at a=b=c.'],r'각 변 \(L/\sqrt3\), 최대부피 \(L^3/(3\sqrt3)\).',r'Each side \(L/\sqrt3\); maximum volume \(L^3/(3\sqrt3)\).')
add(58,r'작물 수확량 \(Y=kNPe^{-N-P}\), k>0,N,P≥0에서 최적 질소·인 수준을 구하라.',r'Maximize crop yield \(Y=kNPe^{-N-P}\) for k>0,N,P≥0.',['Y=k(Ne^(−N))(Pe^(−P))로 분리한다.','t e^(−t)의 미분은(1−t)e^(−t)로 t=1에서 유일한 최대 e^(−1)을 갖는다.'],['Factor Y=k(Ne^(−N))(Pe^(−P)).','The derivative of t e^(−t) is(1−t)e^(−t), giving its unique maximum e^(−1) at t=1.'],'N=P=1, 최대Y=k/e².','N=P=1; maximumY=k/e².')
add(59,'세 종의 비율 pi로 정의한 Shannon 지수 H=−Σpi ln pi를 다룬다. (a) 두 변수 함수 (b) 정의역 (c) 최대값과 비율을 구하라.','For three-species Shannon index H=−Σpi ln pi, find (a) a two-variable expression, (b) its domain, and (c) its maximum and proportions.',[r'(a) p=p₁,q=p₂라 하면 \(H=-p\ln p-q\ln q-(1-p-q)\ln(1-p-q)\).','(b) 로그식 그대로는 p>0,q>0,p+q<1. 0 ln0=0의 연속 확장을 쓰면 닫힌 삼각형도 포함된다.','(c) Hp=ln((1−p−q)/p), Hq=ln((1−p−q)/q)이므로 세 비율1/3. H는 엄격 오목하며 경계는 최대ln2이므로 전역최대이다.'],[r'(a) With p=p₁,q=p₂, \(H=-p\ln p-q\ln q-(1-p-q)\ln(1-p-q)\).','(b) The literal log formula has p>0,q>0,p+q<1. Its continuous extension0 ln0=0 includes the closed triangle.','(c) Hp=ln((1−p−q)/p), Hq=ln((1−p−q)/q), so each proportion is1/3. Strict concavity and boundary maximumln2 establish global maximality.'],'최대ln3, p₁=p₂=p₃=1/3.','Maximumln3 at p₁=p₂=p₃=1/3.','확장 정의역과 로그 자체의 정의역을 구분했다.','The log domain is distinguished from its continuous extension.',['a','b','c'])
add(60,'p,q,r≥0,p+q+r=1일 때 서로 다른 대립유전자 비율 P=2pq+2pr+2qr가2/3 이하임을 보여라.','Show P=2pq+2pr+2qr≤2/3 for nonnegative p,q,r summing to1.',['P=(p+q+r)²−(p²+q²+r²)=1−(p²+q²+r²).','제곱합은 합의 제곱/3 이상이므로 P≤1−1/3.'],['P=1−(p²+q²+r²).','The sum of squares is at least the square of the sum divided by3, so P≤1−1/3.'],'P≤2/3, 등호는 p=q=r=1/3.','P≤2/3, with equality at p=q=r=1/3.')
add(61,r'데이터 (xi,yi)의 잔차제곱합 \(S(m,b)=\sum_i(y_i-mx_i-b)^2\)을 최소화하는 직선의 두 정상방정식을 유도하라.',r'Derive the normal equations for the line minimizing \(S(m,b)=\sum_i(y_i-mx_i-b)^2\).',[r'\(S_b=-2\sum_i(y_i-mx_i-b)=0\).',r'\(S_m=-2\sum_ix_i(y_i-mx_i-b)=0\).','목적함수는 제곱합인 볼록 이차식이므로 정상방정식의 해는 전역최소이다. xi가 모두 같지 않으면 헤세행렬은 양의 정부호로 해가 유일하다.'],[r'\(S_b=-2\sum_i(y_i-mx_i-b)=0\).',r'\(S_m=-2\sum_ix_i(y_i-mx_i-b)=0\).','A sum of squared affine functions is convex, so normal-equation solutions are global minima. If the xi are not all equal, the Hessian is positive definite and the solution is unique.'],r'\(m\sum x_i+nb=\sum y_i\), \(m\sum x_i^2+b\sum x_i=\sum x_iy_i\).',r'\(m\sum x_i+nb=\sum y_i\), \(m\sum x_i^2+b\sum x_i=\sum x_iy_i\).','xi가 모두 같으면 기울기·절편이 따로 유일하지 않아도 그 x에서의 예측값은 평균y이다.','If all xi coincide, slope and intercept are not individually unique, but the fitted value at that x is the mean y.')
add(62,'(1,2,3)을 지나고 첫 팔분공간에서 좌표평면과 최소부피를 자르는 평면을 구하라.','Find the plane through (1,2,3) cutting off the smallest first-octant volume with coordinate planes.',['양의 절편 A,B,C의 평면은 x/A+y/B+z/C=1이며 1/A+2/B+3/C=1.','p=1/A,q=2/B,r=3/C라 놓으면 V=ABC/6=1/(pqr). AM–GM으로 pqr≤1/27이므로 V≥27.'],['Positive intercepts A,B,C satisfy1/A+2/B+3/C=1.','Let p=1/A,q=2/B,r=3/C. Then V=ABC/6=1/(pqr), and AM–GM gives pqr≤1/27, hence V≥27.'],'평면 x/3+y/6+z/9=1, 최소부피27.','Plane x/3+y/6+z/9=1; minimum volume27.')
E.sort(key=lambda a:a['number']);assert [a['number'] for a in E]==list(range(1,63))
D=dict(section='14.7',source=dict(title='Calculus',edition='9',language='en',printedPages=[1054,1055,1056,1057],pdfPages=[1091,1092,1093,1094]),scope=dict(kind='exercise',numbers=list(range(1,63)),total=62,note=pair('전체62문항과 모든 소문항.','All62 exercises and every subpart.')),exercises=E)
(R/'exercise-content/s14-7.json').write_text(json.dumps(D,ensure_ascii=False,indent=2)+'\n')
# Original wireframe plots for explicitly requested graphical exercises.
A=R/'exercise-content/assets'
for n,(F,box) in plots.items():
 fn=S.lambdify((x,y),F,'math');a,b,c,d=box;segments=[];values=[]
 for i in range(25):
  for swap in [False,True]:
   pts=[]
   for j in range(61):
    xx=a+(b-a)*(i/24 if swap else j/60);yy=c+(d-c)*(j/60 if swap else i/24)
    try:zz=fn(xx,yy)
    except (ValueError,ZeroDivisionError):continue
    if math.isfinite(zz):pts.append((xx,yy,zz));values.append(zz)
   segments.append(pts)
 lo=min(values);hi=max(values)
 if n==25:lo=3;hi=15
 if n==41:lo=-15;hi=0
 project=lambda xx,yy,zz:(400+190*(xx-a)/(b-a)-140*(yy-c)/(d-c),390+55*(xx-a)/(b-a)+55*(yy-c)/(d-c)-300*(zz-lo)/max(1,hi-lo))
 out=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 850 550"><rect width="850" height="550" fill="white"/>',f'<text x="425" y="30" text-anchor="middle" font-family="sans-serif">14.7.{n}: original function wireframe</text>']
 for pts in segments:
  run=[]
  for xx,yy,zz in pts:
   if lo<=zz<=hi:run.append(project(xx,yy,zz))
